function countLongestRising(nums: number[]): number {
  const n = nums.length;
  let best = 0, count = 0;
  for (let mask = 1; mask < 1 << n; mask++) {
    let prev = -Infinity, size = 0, ok = true;
    for (let i = 0; i < n && ok; i++) {
      if (mask & (1 << i)) {
        if (nums[i] <= prev) ok = false;
        prev = nums[i];
        size++;
      }
    }
    if (!ok) continue;
    if (size > best) { best = size; count = 1; }
    else if (size === best) count++;
  }
  return count;
}

