    def countLongestRising(self, nums: List[int]) -> int:
        n = len(nums)
        best = count = 0
        for mask in range(1, 1 << n):
            picked = [nums[i] for i in range(n) if mask >> i & 1]
            if any(a >= b for a, b in zip(picked, picked[1:])):
                continue
            if len(picked) > best:
                best, count = len(picked), 1
            elif len(picked) == best:
                count += 1
        return count

