function countLongestRising(nums: number[]): number {
  const sorted = [...new Set(nums)].sort((a, b) => a - b);
  const rank = new Map<number, number>();
  sorted.forEach((v, i) => rank.set(v, i + 1));
  const m = sorted.length;
  const bestLen = new Array(m + 1).fill(0), bestCnt = new Array(m + 1).fill(0);
  // merge (l, c) into the pair stored at slot i
  const merge = (i: number, l: number, c: number): void => {
    if (l > bestLen[i]) { bestLen[i] = l; bestCnt[i] = c; }
    else if (l === bestLen[i]) bestCnt[i] += c;
  };
  for (const x of nums) {
    const k = rank.get(x)!;
    // best pair among ranks 1 .. k - 1
    let l = 0, c = 0;
    for (let i = k - 1; i > 0; i -= i & -i) {
      if (bestLen[i] > l) { l = bestLen[i]; c = bestCnt[i]; }
      else if (bestLen[i] === l) c += bestCnt[i];
    }
    const nl = l + 1, nc = l === 0 ? 1 : c;
    for (let i = k; i <= m; i += i & -i) merge(i, nl, nc);
  }
  let l = 0, c = 0;
  for (let i = m; i > 0; i -= i & -i) {
    if (bestLen[i] > l) { l = bestLen[i]; c = bestCnt[i]; }
    else if (bestLen[i] === l) c += bestCnt[i];
  }
  return c;
}

