class Solution:
    def countLongestRising(self, nums: List[int]) -> int:
        rank = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
        m = len(rank)
        best_len, best_cnt = [0] * (m + 1), [0] * (m + 1)

        def query(i):
            l = c = 0
            while i > 0:
                if best_len[i] > l:
                    l, c = best_len[i], best_cnt[i]
                elif best_len[i] == l:
                    c += best_cnt[i]
                i -= i & -i
            return l, c

        for x in nums:
            k = rank[x]
            l, c = query(k - 1)
            nl, nc = l + 1, (c if l else 1)
            i = k
            while i <= m:
                if nl > best_len[i]:
                    best_len[i], best_cnt[i] = nl, nc
                elif nl == best_len[i]:
                    best_cnt[i] += nc
                i += i & -i
        return query(m)[1]

